import csv
for p in ['rmsd_backbone_domains.csv', 'rmsd_ca_core.csv', 'rmsd_mass_weighted.csv', 'rmsd_resid_weighted.csv']:
    with open(p) as f:
        rows = list(csv.reader(f))
    hdr = rows[0]
    n = len(rows) - 1
    assert n > 2
    for i, r in enumerate(rows[1:]):
        for j in range(1, len(hdr)):
            v = float(r[j].split('(')[-1].rstrip(')')) if '(' in r[j] else float(r[j])
            if i == 0 and j == 1:
                r[j] = ('%.17g' % v)
            else:
                r[j] = ('%.17g' % v)
    with open(p, 'w', newline='') as f:
        w = csv.writer(f)
        w.writerow(hdr)
        w.writerows(rows[1:])
    # verify parse-back equality
    with open(p) as f:
        rows2 = list(csv.reader(f))
    def num(s):
        s = s.strip()
        if s.startswith('np.float64('):
            s = s[len('np.float64('):-1]
        return float(s)
    for r1, r2 in zip(rows[1:], rows2[1:]):
        assert r1[0] == r2[0]
        for a, b in zip(r1[1:], r2[1:]):
            assert num(a) == num(b)
    print('rewrote', p, 'rows', n)
